//! Golden test of the nether fortress (`NetherFortressStructure` + `NetherFortressPieces`) against the real vanilla classes
//! (fixture `tests/fixtures/nether_fortress.txt`, generated by `tests/oracle/NetherFortressOracle.java`): the generated start
//! (every piece's saved tag: type, bounding box, orientation, gen depth, extra fields) for 40 seeds/chunks, and `placeInChunk`
//! of the start over synthetic terrain for 101 centre chunks (blocks as a per-chunk digest, block entity NBT: blaze spawner
//! and `chests/nether_bridge` chests, scheduled ticks, heightmaps, post-processing marks, region random). Driver:
//! `common/structure_golden.rs`.

use crate::common::structure_golden::{run_fixture, structure};

#[test]
fn nether_fortress_matches_vanilla() {
    let fortress = structure("fortress");
    let stats = run_fixture("nether_fortress.txt", &|_| &fortress);
    assert!(
        stats.starts >= 40
            && stats.pieces > 3000
            && stats.placements >= 100
            && stats.dump_lines > 5000,
        "fixture too small"
    );
    for id in [
        "nebcr", "nebef", "nebs", "neccs", "nece", "necsr", "nectb", "nemt", "nerc", "nesc",
        "nesclt", "nescrt", "nescsc", "nesr",
    ] {
        assert!(
            stats.piece_ids.contains_key(&format!("minecraft:{id}")),
            "fixture lacks piece {id}: {:?}",
            stats.piece_ids
        );
    }
    assert!(
        stats
            .block_entity_ids
            .get("minecraft:mob_spawner")
            .copied()
            .unwrap_or(0)
            >= 5,
        "no blaze spawners: {:?}",
        stats.block_entity_ids
    );
    assert!(
        stats
            .loot_tables
            .get("minecraft:chests/nether_bridge")
            .copied()
            .unwrap_or(0)
            >= 5,
        "no chests: {:?}",
        stats.loot_tables
    );
}
